add('sentinel', 'CredScan', f"""Credential and private-URL sentinel for this round's new inputs and outputs. Scan (read-only; mask any hit) the files delivered under {W}/ as they appear (re-scan at the end) and the snapshots under {W}/sources/, plus the JSON/record files the C1 bindings point at (census/round-1/, census/round-13/, census/round-21/ records). Patterns: private keys, tokens (ghp_, github_pat_, sk-, xox, AKIA), `op://`, bearer/basic auth headers, `Authorization:`, URLs with userinfo, home-directory secret paths. Report counts per pattern with the commands; 0 hits needs the sweep.""")
add('simplifier', 'SpecHygiene', f"""Validate this wave's spec hygiene. Read {L}/.ufo/waves/round-32/make-spec-w1.py (generator; read-only) and the rendered plan {L}/.ufo/waves/round-32/w1-dispatch.json. Check: distinct item ids and prompts; roles only from scout, reviewer, critic, connector, sentinel, executor, mutation-tester, revenger, simplifier, scribe; flash roles (executor, scribe, critic, sentinel, revenger, simplifier) >= 50 % and attack roles (reviewer, critic, mutation-tester) >= 25 % of seats; every path absolute; no item asks a seat to write outside {W}/ or its scratch; every scratch path under {SCR}/; no two items deliver the same file (C2 executors deliver whole patched files named by basename — check no two own the same file). Report defects with item ids.""")

c = collections.Counter(i['role'] for i in ITEMS)
n = len(ITEMS)
assert len({i['item'] for i in ITEMS}) == n and len({i['prompt'] for i in ITEMS}) == n
flash = sum(c[r] for r in ('executor', 'scribe', 'critic', 'sentinel', 'revenger', 'simplifier'))
attack = sum(c[r] for r in ('reviewer', 'critic', 'mutation-tester'))
assert 32 <= n <= 64 and flash * 2 >= n and attack * 4 >= n, (n, flash, attack)
spec = {'wave': 'souji-r32-w1', 'reportDir': '.ufo/waves/round-32/w1', 'maxLanes': 64, 'context': CONTEXT, 'items': ITEMS}
json.dump(spec, open(L + '/.ufo/waves/round-32/w1-spec.json', 'w'), ensure_ascii=False, indent=1)
print(n, dict(c), 'flash', flash, 'attack', attack)
